    /**
     * Compara el contenido de esta versión contra la versión actual, párrafo por párrafo: los
     * párrafos sin cambios se muestran con su formato original intacto (centrado, justificado,
     * encabezados en negrita), y solo los que cambiaron se resaltan por palabra dentro de ese
     * mismo formato. Diferenciar el HTML crudo carácter por carácter (sin este paso por bloques)
     * deja que la librería de diff corte justo en medio de una etiqueta y deje markup roto visible
     * en el resultado; diferenciar puro texto plano sin bloques pierde todo el formato visual.
    */
    public function compareVersions($renderType = 'Inline')
    {
        try {
            $current_docversion = DocsControlCambioPeer::getCurrentVersionDoc($this->getConsecutivoId(), $this->getModuloId());

            if (empty($current_docversion) || empty($this)) {
                throw new Exception("Una o ambas versiones no existen");
            }
            //*********************************************************************************************
            $oldContent = $this->getContenidoText();
            $newContent = $current_docversion->getContenidoText();

            if ($oldContent == null || $newContent == null) {
                throw new Exception("Una o ambas versiones no existen");
            }
            //*********************************************************************************************
            $oldBlocks = $this->extraerBloquesParaComparar($oldContent);
            $newBlocks = $this->extraerBloquesParaComparar($newContent);
            //*********************************************************************************************
            $oldTexts = array_map(function ($bloque) { return $bloque['text']; }, $oldBlocks);
            $newTexts = array_map(function ($bloque) { return $bloque['text']; }, $newBlocks);
            //*********************************************************************************************
