    /**
     * Extrae los párrafos/bloques de un HTML (párrafos, divs, encabezados, ítems de lista) para
     * comparar de a uno, conservando el estilo propio de cada uno y si está en negrita completa.
     */
    private function extraerBloquesParaComparar($html)
    {
        $bloques = array();
        $html = trim((string) $html);
        if ($html === '') {
            return $bloques;
        }
        //*********************************************************************************************
        $dom = new \DOMDocument();
        libxml_use_internal_errors(true);
        $dom->loadHTML('<?xml encoding="utf-8" ?><div id="___raiz___">' . $html . '</div>', LIBXML_NOWARNING | LIBXML_NOERROR);
        libxml_clear_errors();
        //*********************************************************************************************
        $raiz = $dom->getElementById('___raiz___');
        if ($raiz === null) {
            return $bloques;
        }
        //*********************************************************************************************
        foreach ($raiz->childNodes as $nodo) {
            if ($nodo->nodeType !== XML_ELEMENT_NODE) {
                continue;
            }
            $texto = trim(preg_replace('/\s+/', ' ', $nodo->textContent));
            if ($texto === '') {
                continue;
            }
            $bloques[] = array(
                'style' => $nodo->hasAttribute('style') ? $nodo->getAttribute('style') : '',
                'bold' => $this->bloqueEsNegrita($nodo),
                'text' => $texto,
            );
        }
        //*********************************************************************************************
        return $bloques;
    }

    /**
     * Un bloque se considera "en negrita completa" si es un encabezado (h1-h6) o si todo su
     * contenido está envuelto en <strong>/<b> - suficiente para los encabezados típicos de las
     * resoluciones (ej. "EL SECRETARIO GENERAL...") sin necesitar comparar carácter por carácter
     * qué partes puntuales están en negrita.
     */
    private function bloqueEsNegrita(\DOMElement $nodo)
    {
        if (preg_match('/^h[1-6]$/i', $nodo->nodeName)) {
            return true;
        }
        $texto = trim($nodo->textContent);
        if ($texto === '') {
            return false;
        }
        foreach (array('strong', 'b') as $tagNegrita) {
            foreach ($nodo->getElementsByTagName($tagNegrita) as $elemento) {
                if (trim($elemento->textContent) === $texto) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Resalta, palabra por palabra, las diferencias entre dos líneas de texto -reutilizando el
     * mismo renderizador de palabras que usa la librería de diff- y devuelve cada lado ya con
     * <ins>/<del> en las palabras puntuales que cambiaron.
     *
     * @return array{0: string, 1: string} [textoViejoMarcado, textoNuevoMarcado]
     */
    private function marcarDiferenciaPorPalabra($textoViejo, $textoNuevo)
    {
        $mbViejo = new MbString(htmlspecialchars($textoViejo, ENT_QUOTES, 'UTF-8'));
        $mbNuevo = new MbString(htmlspecialchars($textoNuevo, ENT_QUOTES, 'UTF-8'));
        //*********************************************************************************************
        LineRendererFactory::make('word', array(), array('wordGlues' => array(' ', '-')))->render($mbViejo, $mbNuevo);
        //*********************************************************************************************
        $viejoMarcado = str_replace(RendererConstant::HTML_CLOSURES, RendererConstant::HTML_CLOSURES_DEL, $mbViejo->get());
        $nuevoMarcado = str_replace(RendererConstant::HTML_CLOSURES, RendererConstant::HTML_CLOSURES_INS, $mbNuevo->get());
        //*********************************************************************************************
        return array($viejoMarcado, $nuevoMarcado);
    }

    /**
     * Arma la tabla HTML de diferencias a partir de los opcodes de SequenceMatcher, mostrando
     * cada bloque con su propio formato (estilo/negrita) en vez del formato genérico del
     * renderizador de la librería.
     */
    private function renderTablaComparacion(array $opcodes, array $oldBlocks, array $newBlocks)
    {
        $html = '<table class="diff-wrapper diff diff-html diff-combined"><thead><tr><th>Diferencias</th></tr></thead>';
        //*********************************************************************************************
        foreach ($opcodes as list($tag, $i1, $i2, $j1, $j2)) {
            if ($tag === SequenceMatcher::OP_EQ) {
                for ($k = $i1; $k < $i2; $k++) {
                    $html .= $this->renderBloqueComparado($newBlocks[$j1 + ($k - $i1)], null, 'eq', 'new');
                }
            } elseif ($tag === SequenceMatcher::OP_DEL) {
                for ($k = $i1; $k < $i2; $k++) {
                    $html .= $this->renderBloqueComparado($oldBlocks[$k], null, 'del', 'old');
                }
            } elseif ($tag === SequenceMatcher::OP_INS) {
                for ($k = $j1; $k < $j2; $k++) {
                    $html .= $this->renderBloqueComparado($newBlocks[$k], null, 'ins', 'new');
                }
            } else {
                // OP_REP: puede haber distinta cantidad de párrafos viejos y nuevos en el bloque
                // reemplazado; se emparejan de a uno y el resto se muestra como inserción/eliminación.
                $oldCount = $i2 - $i1;
                $newCount = $j2 - $j1;
                $max = max($oldCount, $newCount);
                for ($k = 0; $k < $max; $k++) {
                    $oldBlock = $k < $oldCount ? $oldBlocks[$i1 + $k] : null;
                    $newBlock = $k < $newCount ? $newBlocks[$j1 + $k] : null;
                    if ($oldBlock !== null && $newBlock !== null) {
                        list($oldMarcado, $newMarcado) = $this->marcarDiferenciaPorPalabra($oldBlock['text'], $newBlock['text']);
                        $html .= $this->renderBloqueComparado($oldBlock, $oldMarcado, 'rep', 'old');
                        $html .= $this->renderBloqueComparado($newBlock, $newMarcado, 'rep', 'new');
                    } elseif ($oldBlock !== null) {
                        $html .= $this->renderBloqueComparado($oldBlock, null, 'del', 'old');
                    } elseif ($newBlock !== null) {
                        $html .= $this->renderBloqueComparado($newBlock, null, 'ins', 'new');
                    }
                }
            }
        }
        //*********************************************************************************************
        return $html . '</table>';
    }

    /**
     * Renderiza una fila de la tabla de diferencias para UN bloque/párrafo, conservando su
     * estilo original (y negrita si corresponde). $contenidoMarcado ya viene con <ins>/<del>
     * cuando aplica, o null para mostrar el texto del bloque tal cual (ya escapado).
