        if ($bloque['bold']) {
            $estilo = ($estilo === '' ? '' : rtrim($estilo, '; ') . '; ') . 'font-weight: bold;';
        }
        //*********************************************************************************************
        $contenido = $contenidoMarcado !== null ? $contenidoMarcado : htmlspecialchars($bloque['text'], ENT_QUOTES, 'UTF-8');
