        return '<tbody class="change change-' . $tipoCambio . '">' .
            '<tr><td class="' . $claseCelda . '" style="' . htmlspecialchars($estilo, ENT_QUOTES, 'UTF-8') . '">' . $contenido . '</td></tr>' .
        '</tbody>';
    }
